package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.Executors;

import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;
import org.lwjgl.system.MemoryStack;

class TripleStoreExplicitInferredTest {

	private static final long[] SUBJECTS = { 1, 2, 3, 4 };
	private static final long[] PREDICATES = { 11, 11, 11, 11 };
	private static final long[] OBJECTS = { 21, 22, 23, 24 };
	private static final long[] CONTEXTS = { 0, 7, 0, 7 };

	private enum Insertion {
		SCALAR,
		ALIGNED,
		PREPARED
	}

	@TempDir
	Path directory;

	@ParameterizedTest
	@EnumSource(Insertion.class)
	void inferredWritesDoNotDuplicateExplicitQuads(Insertion insertion) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc,cspo");
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.startTransaction();
			store.storeTriple(SUBJECTS[0], PREDICATES[0], OBJECTS[0], CONTEXTS[0], true);
			store.storeTriple(SUBJECTS[1], PREDICATES[1], OBJECTS[1], CONTEXTS[1], true);
			store.commit();

			store.startTransaction();
			Set<Integer> rolledBack = insertInferred(store, insertion);
			store.rollback();
			assertEquals(Set.of(2, 3), rolledBack, "only absent quads can be added as inferred");
			assertRows(store, 2, 0);

			store.startTransaction();
			Set<Integer> added = insertInferred(store, insertion);
			store.commit();
			assertEquals(Set.of(2, 3), added, "only absent quads can be added as inferred");
			assertRows(store, 2, 2);
		}

		try (TripleStore reopened = new TripleStore(directory.toFile(), config, null)) {
			assertRows(reopened, 2, 2);
			reopened.startTransaction();
			reopened.removeTriplesByContext(-1, -1, -1, -1, true, ignored -> {
			});
			reopened.removeTriplesByContext(-1, -1, -1, -1, false, ignored -> {
			});
			reopened.commit();
			try (Txn txn = reopened.getTxnManager().createReadTxn();
					LmdbContextIdIterator contexts = reopened.getContexts(txn)) {
				assertNull(contexts.next(), "context counts must return to zero");
			}
		}
	}

	@Test
	void replayedInferredBatchPreservesExplicitPrecedence() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc,cspo")
				.setTripleDBSize(512L * 1024)
				.setAutoGrow(true);
		try (ReplayProbeStore store = new ReplayProbeStore(directory, config)) {
			store.startTransaction();
			store.storeTriple(SUBJECTS[0], PREDICATES[0], OBJECTS[0], CONTEXTS[0], true);
			store.storeTriple(SUBJECTS[1], PREDICATES[1], OBJECTS[1], CONTEXTS[1], true);
			int previousReplays = store.replays;
			store.failNextContextIncrement = true;
			Set<Integer> added = insertInferred(store, Insertion.ALIGNED);
			assertTrue(store.replays > previousReplays, "the batch must replay after the injected capacity failure");
			assertEquals(Set.of(2, 3), added, "replay callbacks must report only the absent inferred quads");
			store.commit();
			assertRows(store, 2, 2);
		}
		try (TripleStore reopened = new TripleStore(directory.toFile(), config, null)) {
			assertRows(reopened, 2, 2);
		}
	}

	private static final class ReplayProbeStore extends TripleStore {
		private boolean failNextContextIncrement;
		private int replays;

		private ReplayProbeStore(Path directory, LmdbStoreConfig config) throws IOException {
			super(directory.toFile(), config, null);
		}

		@Override
		void incrementAlignedContext(MemoryStack stack, long context, int amount) throws IOException {
			if (failNextContextIncrement) {
				failNextContextIncrement = false;
				throw new MapFullException();
			}
			super.incrementAlignedContext(stack, context, amount);
		}

		@Override
		protected void afterMapGrowthReplay() throws IOException {
			replays++;
			super.afterMapGrowthReplay();
		}
	}

	private static Set<Integer> insertInferred(TripleStore store, Insertion insertion) throws Exception {
		Set<Integer> added = new HashSet<>();
		switch (insertion) {
		case SCALAR -> {
			for (int i = 0; i < SUBJECTS.length; i++) {
				if (store.storeTriple(SUBJECTS[i], PREDICATES[i], OBJECTS[i], CONTEXTS[i], false)) {
					added.add(i);
				}
			}
		}
		case ALIGNED -> store.storeTriplesAligned(SUBJECTS, PREDICATES, OBJECTS, CONTEXTS, SUBJECTS.length, false,
				added::add);
		case PREPARED -> {
			try (var executor = Executors.newFixedThreadPool(2)) {
				var task = store.prepareSecondaryIndexesAsync(executor, SUBJECTS, PREDICATES, OBJECTS, CONTEXTS,
						SUBJECTS.length);
				try {
					store.storePreparedTriples(SUBJECTS, PREDICATES, OBJECTS, CONTEXTS, SUBJECTS.length, false,
							true, added::add, task.awaitMain(), task::await);
				} finally {
					task.cancel();
				}
			}
		}
		}
		return added;
	}

	private static void assertRows(TripleStore store, int explicit, int inferred) throws Exception {
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			for (long[] pattern : new long[][] { { -1, -1, -1, -1 }, { -1, 11, -1, -1 },
					{ -1, -1, 21, -1 }, { -1, -1, -1, 7 } }) {
				int expectedExplicit = pattern[2] == 21 || pattern[3] == 7 ? explicit / 2 : explicit;
				int expectedInferred = pattern[2] == 21 ? 0 : pattern[3] == 7 ? inferred / 2 : inferred;
				assertEquals(expectedExplicit, count(store.getTriples(txn, pattern[0], pattern[1], pattern[2],
						pattern[3], true)), "explicit index rows");
				assertEquals(expectedInferred, count(store.getTriples(txn, pattern[0], pattern[1], pattern[2],
						pattern[3], false)), "inferred index rows");
			}
			List<Long> contextsFound = new ArrayList<>();
			try (LmdbContextIdIterator contexts = store.getContexts(txn)) {
				long[] next;
				while ((next = contexts.next()) != null) {
					contextsFound.add(next[0]);
				}
			}
			assertEquals(List.of(0L, 7L), contextsFound);
		}
	}

	private static int count(RecordIterator iterator) throws Exception {
		try (iterator) {
			int count = 0;
			while (iterator.next() != null) {
				count++;
			}
			return count;
		}
	}
}
